<?php
require __DIR__.'/inc/core.php';auth();
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Geçersiz makbuz.');}
$s=db()->prepare('SELECT p.*,q.quote_no,q.total AS quote_total,c.name AS customer_name FROM ek_quote_payments p JOIN quotes q ON q.id=p.quote_id JOIN customers c ON c.id=q.customer_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Makbuz bulunamadı.');}
$sum=db()->prepare('SELECT COALESCE(SUM(amount_cents),0) FROM ek_quote_payments WHERE quote_id=? AND currency=?');
$sum->execute([$p['quote_id'],$p['currency']]);
$paid=(int)$sum->fetchColumn();
$remaining=(int)round((float)$p['quote_total']*100)-$paid;
$qCurrency=db()->prepare('SELECT currency FROM quotes WHERE id=?');$qCurrency->execute([$p['quote_id']]);$currencyMatch=$qCurrency->fetchColumn()===$p['currency'];
$method=['cash'=>'Nakit','bank'=>'Havale / EFT','card'=>'Kart','other'=>'Diğer'];
header('Content-Type: text/html; charset=utf-8');
?>
